static inline uint16_t bswap16(uint16_t x) /* <=== bswap16 */ 
{
    return (((x & 0x00ff) << 8) |
            ((x & 0xff00) >> 8));
}

static inline void /* <=== e1000x_inc_reg_if_not_full */ 
e1000x_inc_reg_if_not_full(uint32_t *mac, int index)
{
    if (mac[index] != 0xffffffff) {
        mac[index]++;
    }
}

